<template><div class="min-h-screen invite-backdrop text-white flex items-center justify-center px-6"><div class="w-full max-w-sm rounded-2xl border border-gold-400/20 bg-ink-900/60 backdrop-blur p-6 text-center"><UIcon name="i-heroicons-envelope" class="w-10 h-10 text-gold-300 mx-auto mb-4" /><h1 class="text-xl font-display font-bold text-gold-100">Verify your email</h1><p class="text-sm text-white/65 mt-3">Open the link sent to {{ currentUser?.email }}, then return here.</p><p v-if="message" class="text-sm mt-4" :class="failed ? 'text-red-300' : 'text-emerald-300'">{{ message }}</p><div class="mt-6 space-y-3"><UButton block color="primary" :loading="checking" @click="check">I've verified my email</UButton><UButton block variant="soft" color="neutral" :loading="sending" @click="resend">Resend email</UButton></div></div></div></template>
<script setup lang="ts">
const { currentUser, refreshEmailVerification, sendVerificationEmail } = useAuth(); const checking = ref(false); const sending = ref(false); const message = ref(''); const failed = ref(false)
async function check() { checking.value = true; if (await refreshEmailVerification()) await navigateTo('/dashboard'); else { failed.value = true; message.value = 'Not verified yet. Please open the email link.' }; checking.value = false }
async function resend() { sending.value = true; try { await sendVerificationEmail(); failed.value = false; message.value = 'A new verification email was sent.' } catch { failed.value = true; message.value = 'Could not resend the email yet.' } finally { sending.value = false } }
</script>
